function [names, values, centroidal] = nominal_parameters_IRB120()
%NOMINAL_PARAMETERS_IRB120 Nominal parameters of the IRB120 Simscape model.
%
%   [names, values] = nominal_parameters_IRB120() returns symbol names and
%   numerical values for every symbol that can appear in theta_base of the
%   ORIGIN-REFERENCED (parallel-axis) model: m_i, Lc_ix/y/z (centre of mass
%   in MDH frame {i}), link dimensions, and Ixx_i..Iyz_i = inertia about the
%   ORIGIN of MDH frame {i}.
%
%   GENERATED by simulink/generate_identification_data.m from the
%   manufacturer description loadrobot('abbIrb120'); do not edit by hand.
%   The centroidal values are expressed in the MDH link frames; the
%   origin-referenced tensor follows from I_o = I_c + m (c'c E3 - c c').

    c.m  = [3.067 3.909 2.944 1.328 0.546 0.137];
    c.L1 = 0.29;
    c.L2 = 0.27;
    c.L3 = 0.07;
    c.L4 = 0.302;
    c.L5 = 0.072;
    c.L6 = 0;
    % centre of mass [x y z] of link i in MDH frame {i} (m)
    c.Lc = [9.77e-05 -0.00012 -0.05159;0.10124 0.00078 -0.00212;0.05791 0.02281 0.00106;0.00041 -0.00015 -0.0773;6.22e-05 -0.00109 3.68e-05;-1.32e-06 0.00017 -0.00706];
    % centroidal inertia [Ixx Iyy Izz Ixy Ixz Iyz] (kg m^2), MDH frame {i} axes
    c.Ic = [0.0142175 0.0144041 0.0104533 -1.28579e-05 -2.31364e-05 1.93404e-05;0.0259548 0.0603111 0.041569 5.72407e-05 -0.00050497 9.83431e-06;0.0126984 0.00835606 0.016713 0.00142884 -0.000182227 -8.01545e-05;0.0052535 0.00401346 0.00284661 -1.31336e-05 -1.6435e-05 2.12765e-05;0.000815468 0.000404891 0.000892825 8.46805e-07 -1.51792e-08 1.61943e-06;0.001 0.001 0.001 0 0 0];
    centroidal = c;

    names = {};  values = [];
    for i = 1:6
        Ic = [c.Ic(i,1) c.Ic(i,4) c.Ic(i,5); c.Ic(i,4) c.Ic(i,2) c.Ic(i,6); c.Ic(i,5) c.Ic(i,6) c.Ic(i,3)];
        p  = c.Lc(i,:).';
        Io = Ic + c.m(i)*((p.'*p)*eye(3) - p*p.');      % parallel-axis theorem
        names  = [names, {sprintf('m%d',i), sprintf('Lc%dx',i), sprintf('Lc%dy',i), sprintf('Lc%dz',i), ...
                  sprintf('Ixx%d',i), sprintf('Iyy%d',i), sprintf('Izz%d',i), ...
                  sprintf('Ixy%d',i), sprintf('Ixz%d',i), sprintf('Iyz%d',i)}]; %#ok<AGROW>
        values = [values, c.m(i), c.Lc(i,:), Io(1,1), Io(2,2), Io(3,3), Io(1,2), Io(1,3), Io(2,3)]; %#ok<AGROW>
    end
    names  = [names, {'L1', 'L2', 'L3', 'L4', 'L5', 'L6', 'g'}];
    values = [values, c.L1, c.L2, c.L3, c.L4, c.L5, c.L6, 9.81];
end
